@Component("inventorySource-handler")
@ProcessingGroup("inventorySource-processing-group")
public class InventorySourceEventHandler {
	
	// core constructor
	InventorySourceEventHandler(EntityManager entityManager) {
        this.entityManager = entityManager;
    }	
	
    /*
     * @param	event CreateInventorySourceEvent
     */
    @EventHandler
    public void handle( CreateInventorySourceEvent event) {
        entityManager.persist(new InventorySource(event.getInventorySourceId(), event.getName(), event.getDomain(), event.getPublisher(), event.getAdSlots(), event.getDeals(), event.getChannel(), event.getPrimaryFormat()));
    }

    /*
     * @param	event UpdateInventorySourceEvent
     */
    @EventHandler
    public InventorySource handle( UpdateInventorySourceEvent event) {
    	entityManager.merge(new InventorySource(event.getInventorySourceId(), event.getName(), event.getDomain(), event.getPublisher(), event.getAdSlots(), event.getDeals(), event.getChannel(), event.getPrimaryFormat()));
    }
    
    /*
     * @param	event DeleteInventorySourceEvent
     */
    @EventHandler
    public void on( DeleteInventorySourceEvent event) {
    	InventorySource entity = new InventorySource();
   
    	// ------------------------------------------
    	// apply the InventorySourceId
    	// ------------------------------------------
    	entity.setInventorySourceId( event.getInventorySourceId() );
    	
    	// ------------------------------------------
    	// add to an Iterable and delete
    	// ------------------------------------------
    	entityManager.remove( entity );
    }    
    
    // attributes
	private final InventorySourceRepository inventorySourceEntityRepository;
    private static final Logger LOGGER 			= Logger.getLogger(InventorySourceEventHandler.class.getName());

}
